using System.Globalization;using Microsoft.EntityFrameworkCore;using PdfSharp.Drawing;using PdfSharp.Pdf;using Produktionsplanung.App.Data;namespace Produktionsplanung.App.Services;
public static class WeeklyPlanPdfService{private static readonly CultureInfo Culture=CultureInfo.GetCultureInfo("de-CH");public static string BuildFileName(DateTime date){var m=Monday(date);return $"OpsCompact-Wochenplan-KW{ISOWeek.GetWeekOfYear(m):00}-{m:yyyy}.pdf";}public static WeeklyPlanPdfResult Export(DateTime date,string filePath){var m=Monday(date);var s=m.AddDays(6);var data=LoadData(m,s);var settings=AppSettingsService.Load();var doc=new PdfDocument();doc.Info.Title=$"OpsCompact Wochenplan KW {ISOWeek.GetWeekOfYear(m):00}";doc.Info.Subject="Produktions- und Personalwochenplan";doc.Info.Author=settings.CompanyName;var pages=Math.Max(1,(int)Math.Ceiling(data.Rows.Count/9d));for(var p=0;p<pages;p++)DrawPage(doc,data.Rows.Skip(p*9).Take(9).ToList(),data,settings,m,s,p+1,pages);var dir=Path.GetDirectoryName(filePath);if(!string.IsNullOrWhiteSpace(dir))Directory.CreateDirectory(dir);doc.Save(filePath);return new(filePath,doc.PageCount,data.Rows.Count,data.RunSlotCount,data.AssignmentCount);}
 private static WeeklyPlanData LoadData(DateTime m,DateTime s){using var db=new AppDbContext();ProductionScheduleService.EnsureMissingRunSlots(db);var slots=db.ProductionRunSlots.AsNoTracking().Include(x=>x.Shift).Include(x=>x.ProductionOrder).ThenInclude(x=>x.Workstation).Where(x=>x.Date.Date>=m&&x.Date.Date<=s).AsEnumerable().ToList();var a=db.PlanningAssignments.AsNoTracking().Include(x=>x.Employee).Include(x=>x.Workstation).Include(x=>x.Shift).Where(x=>x.Date.Date>=m&&x.Date.Date<=s).AsEnumerable().ToList();var keys=slots.Select(x=>new WeeklyPlanRowKey(x.ProductionOrder.WorkstationId,x.ShiftId,x.ProductionOrder.Workstation.Name,x.ProductionOrder.Workstation.Area,x.Shift.Name,x.Shift.StartTime,x.Shift.EndTime)).Concat(a.Where(x=>x.ShiftId.HasValue&&x.Shift is not null).Select(x=>new WeeklyPlanRowKey(x.WorkstationId,x.ShiftId,x.Workstation.Name,x.Workstation.Area,x.Shift!.Name,x.Shift.StartTime,x.Shift.EndTime))).Concat(a.Where(x=>!x.ShiftId.HasValue).Select(x=>new WeeklyPlanRowKey(x.WorkstationId,null,x.Workstation.Name,x.Workstation.Area,"Individuell",x.StartTime,x.EndTime))).DistinctBy(x=>new{x.WorkstationId,x.ShiftId,x.ShiftStart,x.ShiftEnd}).OrderBy(x=>x.WorkstationName).ThenBy(x=>x.ShiftStart).ToList();var coverage=ProductionOrderCoverageService.Load(m,s).Where(x=>x.RunSlotId>0).ToDictionary(x=>x.RunSlotId);var rows=new List<WeeklyPlanPdfRow>();foreach(var k in keys){var cells=new List<WeeklyPlanPdfCell>();for(var i=0;i<7;i++){var day=m.AddDays(i);var cs=slots.Where(x=>day==x.Date.Date&&x.ProductionOrder.WorkstationId==k.WorkstationId&&k.ShiftId.HasValue&&x.ShiftId==k.ShiftId).ToList();var ca=a.Where(x=>day==x.Date.Date&&x.WorkstationId==k.WorkstationId&&(k.ShiftId.HasValue?x.ShiftId==k.ShiftId:!x.ShiftId.HasValue&&x.StartTime==k.ShiftStart&&x.EndTime==k.ShiftEnd)).OrderBy(x=>x.Employee.LastName).ToList();var products=string.Join(" / ",cs.Select(x=>$"{x.ProductionOrder.Product} [{x.ProductionOrder.OrderNumber}] L{x.SequenceNumber}/{Math.Max(1,x.ProductionOrder.PlannedShiftCount)}").Distinct());var people=string.Join(", ",ca.Select(x=>Compact(x.Employee.FirstName,x.Employee.LastName)).Distinct());var required=cs.Count==0?0:cs.Max(x=>x.ProductionOrder.RequiredStaff);var planned=ca.Select(x=>x.EmployeeId).Distinct().Count();var under=cs.Any(x=>coverage.TryGetValue(x.Id,out var c)&&c.CoverageStatus=="Unterbesetzt");cells.Add(new(day,products,people,planned,required,under));}rows.Add(new(k,cells));}return new(rows,slots.Count,a.Count);}
 private static void DrawPage(PdfDocument doc,IReadOnlyList<WeeklyPlanPdfRow> rows,WeeklyPlanData data,AppSettings settings,DateTime m,DateTime s,int pageNo,int pages){var page=doc.AddPage();page.Orientation=PdfSharp.PageOrientation.Landscape;page.Size=PdfSharp.PageSize.A4;using var g=XGraphics.FromPdfPage(page);var navy=XColor.FromArgb(23,58,94),blue=XColor.FromArgb(46,111,167),border=XColor.FromArgb(210,224,238),header=XColor.FromArgb(237,244,250),weekend=XColor.FromArgb(248,250,252),prod=XColor.FromArgb(239,246,255),warn=XColor.FromArgb(255,247,237),muted=XColor.FromArgb(90,107,125);var margin=22d;var title=new XFont("Segoe UI",16,XFontStyleEx.Bold);var small=new XFont("Segoe UI",6.5,XFontStyleEx.Regular);var bold=new XFont("Segoe UI",6.7,XFontStyleEx.Bold);g.DrawRectangle(new XSolidBrush(navy),0,0,page.Width.Point,9);g.DrawString("OpsCompact",title,new XSolidBrush(navy),new XRect(margin,22,180,22),XStringFormats.TopLeft);g.DrawString($"WOCHENPLAN · KW {ISOWeek.GetWeekOfYear(m):00} · {m:dd.MM.yyyy}–{s:dd.MM.yyyy}",new XFont("Segoe UI",8,XFontStyleEx.Bold),new XSolidBrush(blue),new XRect(margin,48,320,14),XStringFormats.TopLeft);var company=string.IsNullOrWhiteSpace(settings.SiteName)?settings.CompanyName:$"{settings.CompanyName} · {settings.SiteName}";g.DrawString($"{company} · Seite {pageNo}/{pages} · {data.RunSlotCount} Produktionsschichten · {data.AssignmentCount} Personaleinsätze",small,new XSolidBrush(muted),new XRect(400,28,page.Width.Point-margin-400,20),XStringFormats.TopRight);var top=80d,wh=95d,sh=70d,dh=(page.Width.Point-2*margin-wh-sh)/7d,hh=32d,rh=rows.Count==0?45:Math.Min(48,(page.Height.Point-top-hh-45)/rows.Count);var x=margin;Header("MASCHINE / ORT",wh);Header("SCHICHT / ZEIT",sh);for(var i=0;i<7;i++){var d=m.AddDays(i);Header($"{d.ToString("ddd",Culture).ToUpperInvariant()}\n{d:dd.MM.}",dh,d.DayOfWeek is DayOfWeek.Saturday or DayOfWeek.Sunday?weekend:header);}var y=top+hh;if(rows.Count==0){g.DrawString("Für diese Woche sind keine Produktionsschichten oder Personaleinsätze geplant.",new XFont("Segoe UI",9,XFontStyleEx.Regular),new XSolidBrush(muted),new XRect(margin,y,page.Width.Point-2*margin,50),XStringFormats.Center);return;}foreach(var r in rows){x=margin;Cell(r.Key.WorkstationName+"\n"+r.Key.Area,wh,XColors.White,bold);Cell(r.Key.ShiftName+"\n"+$"{r.Key.ShiftStart:hh\\:mm}–{r.Key.ShiftEnd:hh\\:mm}",sh,XColors.White,bold);for(var i=0;i<7;i++){var c=r.Cells[i];var fill=c.Understaffed?warn:c.HasProduction?prod:c.Date.DayOfWeek is DayOfWeek.Saturday or DayOfWeek.Sunday?weekend:XColors.White;var text=c.HasProduction?$"{c.ProductText}\n{c.EmployeeText}\nMA {c.PlannedStaff}/{c.RequiredStaff}":c.EmployeeText;Cell(text,dh,fill,c.HasProduction?bold:small);}y+=rh;}void Header(string text,double w,XColor? fill=null){g.DrawRectangle(new XPen(border),new XSolidBrush(fill??header),x,top,w,hh);DrawText(text,new XRect(x+3,top+3,w-6,hh-6),bold,navy,2);x+=w;}void Cell(string text,double w,XColor fill,XFont font){g.DrawRectangle(new XPen(border),new XSolidBrush(fill),x,y,w,rh);DrawText(text,new XRect(x+3,y+3,w-6,rh-6),font,navy,3);x+=w;}void DrawText(string text,XRect rect,XFont font,XColor color,int max){if(string.IsNullOrWhiteSpace(text))return;var lines=text.Split('\n').SelectMany(z=>Wrap(z,font,rect.Width)).Take(max).ToList();for(var i=0;i<lines.Count;i++)g.DrawString(lines[i],font,new XSolidBrush(color),new XRect(rect.X,rect.Y+i*(font.Size+2),rect.Width,font.Size+3),XStringFormats.TopLeft);}IEnumerable<string> Wrap(string text,XFont font,double width){var words=text.Split(' ',StringSplitOptions.RemoveEmptyEntries);var line="";foreach(var word in words){var next=line.Length==0?word:line+" "+word;if(line.Length==0||g.MeasureString(next,font).Width<=width)line=next;else{yield return line;line=word;}}if(line.Length>0)yield return line;}}
 private static string Compact(string first,string last)=>string.IsNullOrWhiteSpace(first)?last.Trim():$"{last.Trim()} {char.ToUpperInvariant(first.Trim()[0])}.";private static DateTime Monday(DateTime d){var days=(7+((int)d.DayOfWeek-(int)DayOfWeek.Monday))%7;return d.Date.AddDays(-days);}}
public sealed record WeeklyPlanPdfResult(string FilePath,int PageCount,int RowCount,int ProductionShiftCount,int AssignmentCount);internal sealed record WeeklyPlanData(IReadOnlyList<WeeklyPlanPdfRow> Rows,int RunSlotCount,int AssignmentCount);internal sealed record WeeklyPlanRowKey(int WorkstationId,int? ShiftId,string WorkstationName,string Area,string ShiftName,TimeSpan ShiftStart,TimeSpan ShiftEnd);internal sealed record WeeklyPlanPdfRow(WeeklyPlanRowKey Key,IReadOnlyList<WeeklyPlanPdfCell> Cells);internal sealed record WeeklyPlanPdfCell(DateTime Date,string ProductText,string EmployeeText,int PlannedStaff,int RequiredStaff,bool Understaffed){public bool HasProduction=>!string.IsNullOrWhiteSpace(ProductText);}
